public int FindKthLargestSort(int[] nums, int k)
{
    Array.Sort(nums);
    // After ascending sort, the kth largest is at n - k
    return nums[nums.Length - k];
}

public int FindKthLargest(int[] nums, int k)
{
    // .NET's PriorityQueue is a min-heap by default
    var heap = new PriorityQueue<int, int>();

    foreach (int value in nums)
    {
        heap.Enqueue(value, value);

        // Keep only the k largest values
        if (heap.Count > k)
        {
            heap.Dequeue();
        }
    }

    return heap.Peek();
}

public int FindKthLargestQuickSelect(int[] nums, int k)
{
    int target = nums.Length - k; // index in ascending order
    int left = 0, right = nums.Length - 1;

    var random = new Random();

    while (left <= right)
    {
        int pivotIndex = Partition(nums, left, right, random.Next(left, right + 1));

        if (pivotIndex == target) return nums[pivotIndex];
        if (pivotIndex < target) left = pivotIndex + 1;
        else right = pivotIndex - 1;
    }

    return nums[target];
}

private static int Partition(int[] nums, int left, int right, int pivotIndex)
{
    int pivotValue = nums[pivotIndex];
    Swap(nums, pivotIndex, right);

    int store = left;
    for (int i = left; i < right; i++)
    {
        if (nums[i] < pivotValue)
        {
            Swap(nums, i, store++);
        }
    }

    Swap(nums, store, right);
    return store;
}

private static void Swap(int[] a, int i, int j) => (a[i], a[j]) = (a[j], a[i]);

public int FindKthLargest(int[] nums, int k)
{
    var heap = new PriorityQueue<int, int>();

    foreach (int value in nums)
    {
        heap.Enqueue(value, value);
        if (heap.Count > k) heap.Dequeue();
    }

    return heap.Peek();
}
